197	func parseHex4(b []byte) (int, bool) {
198		v := 0
199		for _, c := range b {
200			v <<= 4
201			switch {
202			case c >= '0' && c <= '9':
203				v += int(c - '0')
204			case c >= 'a' && c <= 'f':
205				v += int(c-'a') + 10
206			case c >= 'A' && c <= 'F':
207				v += int(c-'A') + 10
208			default:
209				return 0, false
210			}
211		}
212		return v, true
213	}
