250				t.Fatalf("writer %d: status = %d, want 201", i, codes[i])
251			}
252			if seen[seqs[i]] {
253				t.Fatalf("duplicate seq %v", seqs[i])
254			}
255			seen[seqs[i]] = true
256		}
257		for seq := float64(1); seq <= writers; seq++ {
258			if !seen[seq] {
259				t.Fatalf("seq %v missing, got %v", seq, seen)
260			}
261		}
