375	func TestPostEventAcceptsBoundaryUTCYear(t *testing.T) {
376		path := filepath.Join(t.TempDir(), "service.db")
377		st, err := store.Open(path)
378		if err != nil {
379			t.Fatalf("open: %v", err)
380		}
381		defer st.Close()
382		router := NewRouter(st)
383	
384		cases := []struct {
385			occurredAt string
386			wantUTC    string
387		}{
388			// One minute inside the lower bound: UTC lands exactly on 0000-01-01T00:00:00Z.
389			{"0000-01-01T00:01:00+00:01", "0000-01-01T00:00:00Z"},
390			// One minute inside the upper bound: UTC lands exactly on 9999-12-31T23:59:59Z.
391			{"9999-12-31T23:58:59-00:01", "9999-12-31T23:59:59Z"},
392		}
393		prevHash := strings.Repeat("0", 64)
394		for i, tc := range cases {
395			recorder := postEventBody(t, router,
396				fmt.Sprintf(`{"account":"a","operation":"o","resource":"r","result":"ok","occurred_at":%q}`, tc.occurredAt))
397			if recorder.Code != http.StatusCreated {
398				t.Fatalf("%s: status = %d (%s)", tc.occurredAt, recorder.Code, recorder.Body.String())
399			}
400			event := decodeEvent(t, recorder)
401			if event["occurred_at"] != tc.wantUTC {
402				t.Fatalf("%s: occurred_at = %v, want %v", tc.occurredAt, event["occurred_at"], tc.wantUTC)
403			}
404			seq := int64(i + 1)
405			if event["seq"] != float64(seq) {
406				t.Fatalf("%s: seq = %v, want %d", tc.occurredAt, event["seq"], seq)
407			}
408			want := wantHash(seq, "a", "o", "r", "ok", tc.wantUTC, prevHash)
409			if event["hash"] != want {
410				t.Fatalf("%s: hash = %v, want %v (normalized time must feed the hash)", tc.occurredAt, event["hash"], want)
411			}
412			prevHash = event["hash"].(string)
413		}
414	
415		// The persisted rows carry the same normalized UTC timestamps.
416		stored := readStoredEvents(t, path)
417		if len(stored) != len(cases) {
418			t.Fatalf("stored %d events, want %d", len(stored), len(cases))
419		}
420		for i, tc := range cases {
421			if stored[i].occurredAt != tc.wantUTC {
422				t.Fatalf("stored occurred_at = %v, want %v", stored[i].occurredAt, tc.wantUTC)
423			}
424		}
425	}
